// ============================================================
// BLOOM — minified site JavaScript (production-ready)
// Handles navigation, scroll, tab panels, and hash routing.
// No dependencies - pure vanilla JS for maximum compatibility.
// ============================================================

(function() {
'use strict';

var reduceMotion = window.matchMedia("(prefers-reduced-motion: reduce)").matches;

/** Scrolls to an element with reduced motion awareness */
function scrollToEl(el, extra) {
  if (!el) return;
  var header = document.querySelector(".site-header");
  var offset = (header ? header.getBoundingClientRect().height : 0) + (extra || 16);
  var top = el.getBoundingClientRect().top + window.scrollY - offset;
  window.scrollTo({ top: Math.max(top, 0), behavior: reduceMotion ? "auto" : "smooth" });
}

// ========== Mobile Navigation ==========
var toggle = document.querySelector(".nav-toggle");
var links = document.querySelector(".nav-links");
if (toggle && links) {
  toggle.addEventListener("click", function() {
    var isOpen = links.classList.toggle("is-open");
    toggle.setAttribute("aria-expanded", isOpen ? "true" : "false");
  });
  links.querySelectorAll("a").forEach(function(link) {
    link.addEventListener("click", function() {
      links.classList.remove("is-open");
      toggle.setAttribute("aria-expanded", "false");
    });
  });
  document.addEventListener("keydown", function(e) {
    if (e.key === "Escape" && links.classList.contains("is-open")) {
      links.classList.remove("is-open");
      toggle.setAttribute("aria-expanded", "false");
      toggle.focus();
    }
  });
}

// ========== Music: Release Tracklists ==========
var releases = Array.prototype.slice.call(document.querySelectorAll("[data-release]"));
function openRelease(release) {
  if (!release) return;
  var details = release.querySelector(".release-details");
  if (details && !details.open) details.open = true;
}
function closeOtherReleases(except) {
  releases.forEach(function(release) {
    if (release === except) return;
    var details = release.querySelector(".release-details");
    if (details && details.open) details.open = false;
  });
}
document.querySelectorAll('a[href^="#album-"]').forEach(function(link) {
  link.addEventListener("click", function(e) {
    var target = document.querySelector(link.getAttribute("href"));
    if (!target) return;
    e.preventDefault();
    var release = target.closest("[data-release]");
    openRelease(release);
    closeOtherReleases(release);
    history.replaceState(null, "", link.getAttribute("href"));
    scrollToEl(release, 8);
  });
});

// ========== Music: Individual Songs ==========
var trackButtons = Array.prototype.slice.call(document.querySelectorAll(".track-toggle"));
function setTrack(button, open) {
  var panel = document.getElementById(button.getAttribute("aria-controls"));
  button.setAttribute("aria-expanded", open ? "true" : "false");
  if (panel) panel.hidden = !open;
}
trackButtons.forEach(function(button) {
  setTrack(button, false);
  button.addEventListener("click", function() {
    var isOpen = button.getAttribute("aria-expanded") === "true";
    setTrack(button, !isOpen);
  });
});

// ========== Music: Lyric Notes ==========
document.querySelectorAll(".track").forEach(function(track) {
  var lyrics = track.querySelector(".lyrics-body");
  var notes = Array.prototype.slice.call(track.querySelectorAll(".note"));
  if (!lyrics || !notes.length) return;
  function activate(index) {
    lyrics.querySelectorAll(".lyric-annot").forEach(function(b) {
      b.classList.toggle("is-active", b.dataset.note === index);
    });
    notes.forEach(function(note) {
      var on = note.dataset.note === index;
      note.classList.toggle("is-active", on);
      if (on && !reduceMotion && note.scrollIntoView) {
        note.scrollIntoView({ block: "nearest", behavior: "smooth" });
      }
    });
  }
  lyrics.querySelectorAll(".lyric-annot").forEach(function(btn) {
    btn.addEventListener("click", function() {
      var already = btn.classList.contains("is-active");
      if (already) {
        activate(null);
        return;
      }
      activate(btn.dataset.note);
    });
  });
});

// ========== Music: Hash Routing ==========
function revealHash(hash, shouldScroll) {
  if (!hash || hash.length < 2) return false;
  var target = document.getElementById(hash);
  if (!target) return false;
  var track = target.closest(".track");
  if (track) {
    var release = track.closest("[data-release]");
    openRelease(release);
    var button = track.querySelector(".track-toggle");
    if (button) setTrack(button, true);
    if (shouldScroll) {
      window.setTimeout(function() { scrollToEl(track, 14); }, 40);
    }
    return true;
  }
  var rel = target.closest("[data-release]");
  if (rel) {
    openRelease(rel);
    if (shouldScroll) {
      window.setTimeout(function() { scrollToEl(rel, 14); }, 40);
    }
    return true;
  }
  return false;
}
if (location.hash) revealHash(location.hash.slice(1), true);
window.addEventListener("hashchange", function() { revealHash(location.hash.slice(1), true); });
document.querySelectorAll('a[href^="#track-"]').forEach(function(link) {
  link.addEventListener("click", function(e) {
    var hash = link.getAttribute("href").slice(1);
    if (!revealHash(hash, false)) return;
    e.preventDefault();
    history.replaceState(null, "", "#" + hash);
    var el = document.getElementById(hash);
    if (el) window.setTimeout(function() { scrollToEl(el, 14); }, 40);
  });
});

// ========== Member Tabs ==========
var tabs = document.querySelector(".tabs");
var buttons = Array.prototype.slice.call(document.querySelectorAll(".tab-button"));
var panels = Array.prototype.slice.call(document.querySelectorAll(".member-panel"));
var panelWrap = document.querySelector(".tab-panels");
if (!tabs || !buttons.length || !panels.length) return;
var indicator = tabs.querySelector(".tab-indicator");
function resizePanels() {
  if (!panelWrap) return;
  var active = panelWrap.querySelector(".member-panel.is-active");
  if (!active) return;
  panelWrap.style.height = "auto";
  panelWrap.style.height = Math.ceil(active.getBoundingClientRect().height) + "px";
}
function moveIndicator(btn) {
  if (!indicator || !btn) return;
  indicator.style.left = btn.offsetLeft + "px";
  indicator.style.width = btn.offsetWidth + "px";
  if (tabs.scrollWidth > tabs.clientWidth) {
    var overflow = btn.offsetLeft + btn.offsetWidth - tabs.clientWidth;
    if (overflow > 0) {
      tabs.scrollLeft = overflow + 16;
    } else if (btn.offsetLeft < tabs.scrollLeft) {
      tabs.scrollLeft = Math.max(btn.offsetLeft - 16, 0);
    }
  }
}
function activateMember(id, shouldScroll) {
  if (!id) return false;
  var target = buttons.filter(function(b) { return b.dataset.target === id; })[0];
  if (!target) return false;
  buttons.forEach(function(b) {
    var active = b === target;
    b.classList.toggle("is-active", active);
    b.setAttribute("aria-selected", active ? "true" : "false");
    b.setAttribute("tabindex", active ? "0" : "-1");
  });
  panels.forEach(function(p) { p.classList.toggle("is-active", p.id === id); });
  resizePanels();
  moveIndicator(target);
  if (shouldScroll) {
    var profiles = document.getElementById("member-profiles");
    if (profiles) {
      var header = document.querySelector(".site-header");
      var offset = (header ? header.getBoundingClientRect().height : 0) + 16;
      var top = profiles.getBoundingClientRect().top + window.scrollY - offset;
      window.scrollTo({ top: Math.max(top, 0), behavior: reduceMotion ? "auto" : "smooth" });
    }
  }
  return true;
}
buttons.forEach(function(btn) {
  btn.addEventListener("click", function() { activateMember(btn.dataset.target, false); });
});
tabs.addEventListener("keydown", function(e) {
  var current = buttons.indexOf(document.activeElement);
  if (current === -1) return;
  var next = null;
  if (e.key === "ArrowRight") next = (current + 1) % buttons.length;
  if (e.key === "ArrowLeft") next = (current - 1 + buttons.length) % buttons.length;
  if (e.key === "Home") next = 0;
  if (e.key === "End") next = buttons.length - 1;
  if (next === null) return;
  e.preventDefault();
  buttons[next].focus();
  activateMember(buttons[next].dataset.target, false);
});
document.querySelectorAll('a[href*="#member-"]').forEach(function(link) {
  link.addEventListener("click", function(e) {
    var hash = link.getAttribute("href").split("#")[1];
    if (!hash) return;
    if (activateMember(hash, true)) {
      e.preventDefault();
      history.replaceState(null, "", "#" + hash);
    }
  });
});
var relayout = function() { resizePanels(); var active = document.querySelector(".tab-button.is-active"); if (active) moveIndicator(active); };
window.addEventListener("resize", relayout);
window.addEventListener("load", relayout);
if (document.fonts && document.fonts.ready) { document.fonts.ready.then(relayout); }
var initial = location.hash.slice(1);
if (initial && activateMember(initial, false)) {
  requestAnimationFrame(function() { requestAnimationFrame(function() { activateMember(initial, true); }); });
} else {
  activateMember(buttons[0].dataset.target, false);
}
})();
